use super::*;
use std::{collections::BTreeMap,fs,path::{Path,PathBuf},sync::{Mutex,atomic::{AtomicBool,Ordering}},time::Instant};
static SERIAL:Mutex<()>=Mutex::new(());
fn route()->Route{Route::from_env(|key|match key{"DISPLAY"=>Some(":54321".into()),"HOME"=>Some("/synthetic/clipboard-home".into()),_=>None}).unwrap()}
fn req(route:&Route)->Request{Request{version:1,request_id:"ab".repeat(16),backend:route.backend,route_hash:route.hash()}}
fn frame(request:&Request,body:&[u8])->Vec<u8>{let h=Header{version:1,request_id:request.request_id.clone(),route_hash:request.route_hash.clone(),status:Status::Text,bytes:body.len(),sha256:sha(body)};let mut bytes=serde_json::to_vec(&h).unwrap();bytes.push(b'\n');bytes.extend_from_slice(body);bytes}
fn altered(request:&Request,change:impl FnOnce(&mut serde_json::Value))->Vec<u8>{let bytes=frame(request,b"private fixture");let at=bytes.iter().position(|b|*b==b'\n').unwrap();let mut value:serde_json::Value=serde_json::from_slice(&bytes[..at]).unwrap();change(&mut value);let mut out=serde_json::to_vec(&value).unwrap();out.push(b'\n');out.extend_from_slice(&bytes[at+1..]);out}
#[test]fn exact_utf8_bytes_and_controls_round_trip_without_prompt_or_logs(){let route=route();let request=req(&route);let text="São João 🐾\n\0copied";let mut bytes=vec![];assert!(serve(&request.bytes().unwrap()[..],&mut bytes,&route,||Reply::Text(text.into())).is_ok());assert!(matches!(decode(bytes,&request),Ok(Reply::Text(value))if value==text));}
#[test]fn missing_wrong_nonce_route_version_and_extra_fields_are_refused(){let request=req(&route());for change in[0,1,2,3,4,5]{let bytes=altered(&request,|h|match change{0=>{h["version"]=2.into();},1=>{h["requestId"]="cd".repeat(16).into();},2=>{h["routeHash"]="ee".repeat(32).into();},3=>{h["unexpected"]="untrusted".into();},4=>{h.as_object_mut().unwrap().remove("requestId");},_=>{h["bytes"]=0.into();}});assert!(matches!(decode(bytes,&request),Err(Failure::Protocol)));}}
#[test]fn length_hash_utf8_truncation_trailing_bytes_and_header_bound_are_enforced(){let request=req(&route());let mut wrong_hash=frame(&request,b"private fixture");*wrong_hash.last_mut().unwrap()=b'x';let mut truncated=frame(&request,b"private fixture");truncated.pop();let mut extra=frame(&request,b"private fixture");extra.push(0);for bytes in[wrong_hash,truncated,extra,frame(&request,&[0xff]),vec![b'x';MAX_HEADER+2],frame(&request,&vec![b'x';MAX_TEXT+1])]{assert!(matches!(decode(bytes,&request),Err(Failure::Protocol)));}}
#[test]fn protocol_rejects_duplicate_header_keys(){let request=req(&route());let frame=frame(&request,b"x");let mut duplicate=b"{\"version\":1,".to_vec();duplicate.extend_from_slice(&frame[1..]);assert!(matches!(decode(duplicate,&request),Err(Failure::Protocol)));}
#[test]fn empty_unavailable_and_too_large_are_not_text_or_successful_data(){let route=route();let request=req(&route);for which in[0,1,2,3]{let mut bytes=vec![];serve(&request.bytes().unwrap()[..],&mut bytes,&route,||match which{0=>Reply::Empty,1=>Reply::Unavailable,3=>Reply::Vacant,_=>Reply::Text("x".repeat(MAX_TEXT+1))}).unwrap();let reply=decode(bytes,&request).unwrap_or_else(|_|panic!("valid status frame"));assert!(matches!((which,reply),(0,Reply::Empty)|(1,Reply::Unavailable)|(2,Reply::TooLarge)|(3,Reply::Vacant)));}}
#[test]fn malformed_requests_never_enter_the_native_clipboard(){let route=route();let request=req(&route);let valid=request.bytes().unwrap();let mut bad_route:serde_json::Value=serde_json::from_slice(&valid).unwrap();bad_route["routeHash"]="00".repeat(32).into();let mut bad=serde_json::to_vec(&bad_route).unwrap();bad.push(b'\n');for input in[b"{}\n".to_vec(),b"{\"version\":true}\n".to_vec(),b"not json\n".to_vec(),vec![b'x';MAX_REQUEST+1],b"{}\n{}\n".to_vec(),bad]{let called=AtomicBool::new(false);assert!(serve(&input[..],vec![],&route,||{called.store(true,Ordering::Release);Reply::Empty}).is_err());assert!(!called.load(Ordering::Acquire));}}
#[test]fn logical_route_is_explicit_and_never_silently_switches_backend(){
 let env=|key:&str|match key{"WAYLAND_DISPLAY"=>Some("wayland-private".into()),"XDG_RUNTIME_DIR"=>Some("/synthetic/runtime".into()),"DISPLAY"=>Some(":1".into()),_=>None};let wayland=Route::from_env(env).unwrap();assert!(wayland.backend==Backend::Wayland);let mut command=Command::new("/usr/bin/true");wayland.apply(&mut command);let vars:BTreeMap<_,_>=command.get_envs().collect();assert_eq!(vars[std::ffi::OsStr::new("DISPLAY")],None);assert_eq!(vars[std::ffi::OsStr::new("WAYLAND_SOCKET")],None);assert_eq!(vars[std::ffi::OsStr::new("WAYLAND_DISPLAY")],Some(std::ffi::OsStr::new("wayland-private")));
 let inherited=Route::from_env(|key|if key=="WAYLAND_SOCKET"{Some("99".into())}else{env(key)});assert!(inherited.is_none());assert!(Route::from_env(|_|None).is_none());
 let x11=route();assert_ne!(wayland.hash(),x11.hash());let mut other=x11.clone();other.display=":54322".into();assert_ne!(x11.hash(),other.hash());
}
struct Files(PathBuf);
impl Files{fn new()->Self{let p=std::env::temp_dir().join(format!("coucou-clipboard-read-{}",crate::assistant_memory::new_id()));fs::create_dir(&p).unwrap();Self(p)}fn path(&self,name:&str)->PathBuf{self.0.join(name)}}
impl Drop for Files{fn drop(&mut self){let _=fs::remove_dir_all(&self.0);}}
fn python(script:&str,path:&Path)->Command{crate::pet_helper::command("/usr/bin/python3",&["-I".into(),"-c".into(),script.into(),path.to_str().unwrap().into()])}
fn gone(pid:i32)->bool{match fs::read(format!("/proc/{pid}/stat")){Err(e)if e.kind()==std::io::ErrorKind::NotFound=>true,Ok(bytes)=>{let at=bytes.iter().rposition(|b|*b==b')').unwrap();matches!(bytes.get(at+2),Some(b'Z'|b'X'|b'x'))},Err(e)=>panic!("cannot observe own child:{e}")}}
const ECHO:&str=r#"import json,sys,hashlib,os,pathlib
r=json.loads(sys.stdin.buffer.readline())
p=pathlib.Path(sys.argv[1]);p.write_text(str(os.getpid()))
b='São João 🐾'.encode()
h={'version':1,'requestId':r['requestId'],'routeHash':r['routeHash'],'status':'text','bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
sys.stdout.buffer.write(json.dumps(h).encode()+b'\n'+b);sys.stdout.buffer.flush()
"#;
#[test]fn actual_supervisor_preserves_frame_and_collects_the_child_before_return(){let _serial=SERIAL.lock().unwrap();let files=Files::new();let marker=files.path("pid");let route=route();let request=req(&route);let reply=execute_with(&route,&request,python(ECHO,&marker),&||true,&||true).unwrap_or_else(|e|panic!("synthetic worker failed:{e:?}"));assert!(matches!(reply,Reply::Text(text)if text=="São João 🐾"));let pid=fs::read_to_string(marker).unwrap().parse().unwrap();assert!(gone(pid));assert!(crate::pet_helper::Session::acquire(crate::pet_helper::Lane::ClipboardRead,TIMEOUT).is_ok());}
#[test]fn retired_or_changed_route_cannot_spawn(){let _serial=SERIAL.lock().unwrap();let files=Files::new();let marker=files.path("must-not-exist");let route=route();let request=req(&route);for state in[false,true]{let result=execute_with(&route,&request,python(ECHO,&marker),&||state,&||false);assert!(result.is_err());assert!(!marker.exists());}}
const FAMILY:&str=r#"import os,pathlib,sys,time
p=os.fork()
if p==0:
 os.close(1);time.sleep(30);os._exit(0)
m=pathlib.Path(sys.argv[1]);t=m.with_suffix('.tmp');t.write_text(str(os.getpid())+' '+str(p));os.replace(t,m)
time.sleep(30)
"#;
#[test]fn cancelled_blocked_read_reaps_own_family_before_releasing_the_shared_slot(){
 let _serial=SERIAL.lock().unwrap();let files=Files::new();let marker=files.path("pids");let route=route();let request=req(&route);let observed=AtomicBool::new(false);let began=Instant::now();
 let result=execute_with(&route,&request,python(FAMILY,&marker),&||{if marker.exists(){assert!(crate::pet_helper::Session::acquire(crate::pet_helper::Lane::ClipboardRead,TIMEOUT).is_err());observed.store(true,Ordering::Release);false}else{true}},&||true);
 assert!(result.is_err());assert!(observed.load(Ordering::Acquire));assert!(began.elapsed()<Duration::from_secs(3));for pid in fs::read_to_string(marker).unwrap().split_whitespace().map(|p|p.parse().unwrap()){assert!(gone(pid));}assert!(crate::pet_helper::Session::acquire(crate::pet_helper::Lane::ClipboardRead,TIMEOUT).is_ok());
}
#[test]fn overlong_output_is_collected_without_publishing_unbounded_data_or_retry(){let _serial=SERIAL.lock().unwrap();let files=Files::new();let marker=files.path("pid");let route=route();let request=req(&route);let script="import sys,pathlib,os;pathlib.Path(sys.argv[1]).write_text(str(os.getpid()));sys.stdout.buffer.write(b'x'*9000000);sys.stdout.buffer.flush()";assert!(matches!(execute_with(&route,&request,python(script,&marker),&||true,&||true),Err(Failure::Transport)));let pid=fs::read_to_string(marker).unwrap().parse().unwrap();assert!(gone(pid));}
#[test]fn wrong_reply_is_terminal_without_retry_or_canary_in_error(){let _serial=SERIAL.lock().unwrap();let files=Files::new();let marker=files.path("pid");let route=route();let request=req(&route);let script=ECHO.replace("r['requestId']","'00'*16");let result=execute_with(&route,&request,python(&script,&marker),&||true,&||true);assert!(matches!(result,Err(Failure::Protocol)));let pid=fs::read_to_string(marker).unwrap().parse().unwrap();assert!(gone(pid));}
#[test]fn helper_memory_and_cpu_limits_apply_only_to_the_owned_child(){let _serial=SERIAL.lock().unwrap();let files=Files::new();let marker=files.path("limits");let route=route();let request=req(&route);let script=ECHO.replace("p.write_text(str(os.getpid()))","import resource;assert resource.getrlimit(resource.RLIMIT_AS)==(805306368,805306368);assert resource.getrlimit(resource.RLIMIT_CPU)==(2,2);p.write_text(str(os.getpid()))");assert!(matches!(execute_with(&route,&request,python(&script,&marker),&||true,&||true),Ok(Reply::Text(_))));}

#[test]fn maximum_accepted_text_is_read_within_the_original_deadline(){let _serial=SERIAL.lock().unwrap();let files=Files::new();let marker=files.path("pid");let route=route();let request=req(&route);let script=ECHO.replace("'São João 🐾'.encode()","b'x'*(8*1024*1024)");let began=Instant::now();let reply=execute_with(&route,&request,python(&script,&marker),&||true,&||true).unwrap_or_else(|e|panic!("bounded maximum failed:{e:?}"));assert!(matches!(reply,Reply::Text(text)if text.len()==MAX_TEXT));assert!(began.elapsed()<TIMEOUT);let pid=fs::read_to_string(marker).unwrap().parse().unwrap();assert!(gone(pid));}
